mapper.select:
select  from ai_skill_file
where del_flag = '0' and skill_id = #{skillId}
order by rel_path asc

mapper.update:
update ai_skill_file
file_size = #{fileSize}, content_type = #{contentType}, summary = #{summary}, create_by = #{createBy}, create_time = #{createTime},
where file_id = #{fileId}
